#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdint.h>
#include <pthread.h>

#define MAX_REQUESTS_PER_WINDOW 100
#define WINDOW_SIZE_SECONDS 60
#define MAX_CLIENTS 256
#define CLIENT_ID_LEN 64

typedef struct {
    char client_id[CLIENT_ID_LEN];
    uint32_t request_count;
    time_t window_start;
    pthread_mutex_t lock;
} rate_limit_entry_t;

typedef struct {
    rate_limit_entry_t entries[MAX_CLIENTS];
    int num_entries;
    pthread_mutex_t global_lock;
    int max_requests;
    int window_seconds;
} rate_limiter_t;

static rate_limiter_t g_limiter;

static int load_config_from_env(rate_limiter_t *limiter) {
    const char *max_req_str = getenv("PDF_RATE_LIMIT_MAX");
    const char *window_str = getenv("PDF_RATE_LIMIT_WINDOW");

    if (max_req_str != NULL) {
        long val = strtol(max_req_str, NULL, 10);
        if (val > 0 && val <= INT32_MAX) {
            limiter->max_requests = (int)val;
        } else {
            limiter->max_requests = MAX_REQUESTS_PER_WINDOW;
        }
    } else {
        limiter->max_requests = MAX_REQUESTS_PER_WINDOW;
    }

    if (window_str != NULL) {
        long val = strtol(window_str, NULL, 10);
        if (val > 0 && val <= 3600) {
            limiter->window_seconds = (int)val;
        } else {
            limiter->window_seconds = WINDOW_SIZE_SECONDS;
        }
    } else {
        limiter->window_seconds = WINDOW_SIZE_SECONDS;
    }

    return 0;
}

int rate_limiter_init(void) {
    memset(&g_limiter, 0, sizeof(rate_limiter_t));
    pthread_mutex_init(&g_limiter.global_lock, NULL);
    for (int i = 0; i < MAX_CLIENTS; i++) {
        pthread_mutex_init(&g_limiter.entries[i].lock, NULL);
    }
    return load_config_from_env(&g_limiter);
}

static rate_limit_entry_t* find_or_create_entry(const char *client_id) {
    pthread_mutex_lock(&g_limiter.global_lock);

    for (int i = 0; i < g_limiter.num_entries; i++) {
        if (strncmp(g_limiter.entries[i].client_id, client_id, CLIENT_ID_LEN) == 0) {
            pthread_mutex_unlock(&g_limiter.global_lock);
            return &g_limiter.entries[i];
        }
    }

    if (g_limiter.num_entries >= MAX_CLIENTS) {
        pthread_mutex_unlock(&g_limiter.global_lock);
        return NULL;
    }

    rate_limit_entry_t *entry = &g_limiter.entries[g_limiter.num_entries];
    strncpy(entry->client_id, client_id, CLIENT_ID_LEN - 1);
    entry->client_id[CLIENT_ID_LEN - 1] = '\0';
    entry->request_count = 0;
    entry->window_start = time(NULL);
    g_limiter.num_entries++;

    pthread_mutex_unlock(&g_limiter.global_lock);
    return entry;
}

static int check_rate_limit_internal(rate_limit_entry_t *entry) {
    time_t now = time(NULL);

    pthread_mutex_lock(&entry->lock);

    time_t elapsed = now - entry->window_start;

    /* Reset window if elapsed time exceeds window size */
    if (elapsed >= (time_t)g_limiter.window_seconds) {
        entry->window_start = now;
        entry->request_count = 0;
    }

    /* Check if under limit - note: uses post-increment */
    uint32_t current = entry->request_count++;

    pthread_mutex_unlock(&entry->lock);

    /* Allow if current count (before increment) is below max */
    if (current < (uint32_t)g_limiter.max_requests) {
        return 1; /* allowed */
    }

    return 0; /* denied */
}

typedef struct {
    unsigned char *buffer;
    size_t length;
    int status;
} pdf_document_t;

static pdf_document_t* generate_pdf_internal(const char *content, size_t content_len) {
    pdf_document_t *doc = calloc(1, sizeof(pdf_document_t));
    if (!doc) return NULL;

    /* Simplified PDF generation */
    const char *header = "%PDF-1.4\n";
    size_t total = strlen(header) + content_len + 64;
    doc->buffer = malloc(total);
    if (!doc->buffer) {
        free(doc);
        return NULL;
    }

    int written = snprintf((char*)doc->buffer, total,
        "%s1 0 obj\n<< /Type /Catalog >>\nendobj\n%.*s\n%%%%EOF",
        header, (int)content_len, content);
    doc->length = (written > 0) ? (size_t)written : 0;
    doc->status = 0;
    return doc;
}

void pdf_document_free(pdf_document_t *doc) {
    if (doc) {
        free(doc->buffer);
        free(doc);
    }
}

/* Public API: generate PDF with rate limiting */
pdf_document_t* pdf_generate(const char *client_id, const char *content, size_t content_len) {
    if (!client_id || !content || content_len == 0) {
        return NULL;
    }

    rate_limit_entry_t *entry = find_or_create_entry(client_id);
    if (!entry) {
        return NULL;
    }

    /* Reload config on each request to pick up runtime changes */
    load_config_from_env(&g_limiter);

    if (!check_rate_limit_internal(entry)) {
        return NULL; /* rate limited */
    }

    return generate_pdf_internal(content, content_len);
}

/* Diagnostic endpoint for monitoring */
int pdf_get_remaining_quota(const char *client_id) {
    if (!client_id) return -1;

    rate_limit_entry_t *entry = find_or_create_entry(client_id);
    if (!entry) return -1;

    pthread_mutex_lock(&entry->lock);
    int remaining = g_limiter.max_requests - (int)entry->request_count;
    pthread_mutex_unlock(&entry->lock);

    return (remaining > 0) ? remaining : 0;
}
